CREATE TABLE IF NOT EXISTS cloud_session_subagents (session_id VARCHAR(36), id VARCHAR(128), `type` VARCHAR(64) NULL, description VARCHAR(200) NOT NULL, `state` VARCHAR(16) NOT NULL, started_at BIGINT NOT NULL, ended_at BIGINT NULL, steps INT NOT NULL, parent_id VARCHAR(128) NULL, task_id VARCHAR(64) NULL, result_error BOOLEAN NOT NULL, CONSTRAINT pk_cloud_session_subagents PRIMARY KEY (session_id, id), CONSTRAINT cloud_session_subagents_session FOREIGN KEY (session_id) REFERENCES cloud_sessions(id) ON DELETE CASCADE);
CREATE INDEX cloud_subagent_started ON cloud_session_subagents (session_id, started_at);